import sqlite3

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("ci-access")

DB_PATH = "ci_access.db"
VALID_ROLES = {"viewer", "deployer", "admin"}


def _upsert_role(environment, username, role):
    conn = sqlite3.connect(DB_PATH)
    try:
        conn.execute(
            "INSERT INTO environment_roles (environment, username, role) VALUES (?, ?, ?) "
            "ON CONFLICT(environment, username) DO UPDATE SET role = excluded.role",
            (environment, username, role),
        )
        conn.commit()
    finally:
        conn.close()


@mcp.tool()
def grant_deploy_environment_access(environment: str, username: str, role: str) -> str:
    if role not in VALID_ROLES:
        return f"Invalid role '{role}'. Choose from {sorted(VALID_ROLES)}."
    _upsert_role(environment, username, role)
    return f"{username} now has role '{role}' on {environment}."

import json
import sqlite3
from datetime import datetime, timezone

import requests
from agents import function_tool

LOG_DB = "release_log.db"


def _build_payload(service, version, changelog):
    text = f":rocket: *{service}* {version} has been released."
    if changelog:
        text += f"\n{changelog[:1500]}"
    return {"text": text}


def _record(service, version, status, detail):
    conn = sqlite3.connect(LOG_DB)
    try:
        conn.execute(
            "CREATE TABLE IF NOT EXISTS release_notifications "
            "(id INTEGER PRIMARY KEY, service TEXT, version TEXT, status TEXT, detail TEXT, created_at TEXT)"
        )
        conn.execute(
            "INSERT INTO release_notifications (service, version, status, detail, created_at) VALUES (?, ?, ?, ?, ?)",
            (service, version, status, detail, datetime.now(timezone.utc).isoformat()),
        )
        conn.commit()
    finally:
        conn.close()


@function_tool
def notify_release_and_record(service: str, version: str, webhook_url: str, changelog: str = "") -> str:
    payload = _build_payload(service, version, changelog)
    try:
        resp = requests.post(
            webhook_url,
            data=json.dumps(payload),
            headers={"Content-Type": "application/json"},
            timeout=15,
        )
    except requests.RequestException as exc:
        _record(service, version, "error", str(exc))
        return f"Failed to send notification: {exc}"

    if resp.status_code != 200:
        _record(service, version, "failed", f"HTTP {resp.status_code}")
        return f"Slack returned HTTP {resp.status_code}"

    _record(service, version, "sent", "ok")
    return f"Release notification for {service} {version} sent and logged."
